const M=window.FindsModel,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n),norm=s=>String(s).toLowerCase().replace(/[^a-z0-9]/g,'').replace(/ggdb|ggs/g,'goldengoose');
