function snapshot(){return {category,visible,scroll:window.scrollY,filtersOpen:!$('#filters').hidden,values:Object.fromEntries(['query','brand','subcategory','shop','source','sort','imagefilter'].map(id=>[id,$('#'+id).value]))}}
