function restore(saved){$('#filters').hidden=!saved?.filtersOpen;$('#filter-toggle').setAttribute('aria-expanded',!!saved?.filtersOpen);category=saved?.category||'';visible=saved?.visible||40;for(const id of ['query','brand','subcategory','shop','source','sort','imagefilter'])$('#'+id).value=saved?.values?.[id]||(id==='sort'?'pictures':'');populateSubcategories();if(saved?.values?.subcategory)$('#subcategory').value=saved.values.subcategory}
