function selectedGroups(){const q=norm($('#query').value),brand=$('#brand').value,sub=$('#subcategory').value,shop=$('#shop').value,source=$('#source').value,pictures=$('#imagefilter').value;let list=currentGroups().filter(g=>(!category||g.category.main===category)&&(!sub||g.category.sub===sub)&&(!brand||(M.preferred[brand]?(g.names||g.offers.map(o=>o.name)).some(n=>M.preferred[brand].test(n)):g.brand===brand))&&(!shop||g.offers.some(o=>o.shop===shop))&&(!source||g.references.some(r=>r.source===source))&&(!pictures||g.cached)&&(!q||norm(g.name+' '+g.brand+' '+g.category.main+' '+g.category.sub).includes(q)));const order=$('#sort').value;list.sort((a,b)=>order==='low'?(a.price??Infinity)-(b.price??Infinity):order==='high'?(b.price??-Infinity)-(a.price??-Infinity):order==='name'?a.name.localeCompare(b.name):(Number(b.cached)-Number(a.cached)||a.name.localeCompare(b.name)));return list}
function imgHTML(g,detail=false){const image=g.images[detail?imageIndex:0];return image&&mediaUrl(image)?`<img class="productimage" src="${esc(mediaUrl(image))}" alt="${esc(g.name)}" ${detail?'':'loading="lazy"'} decoding="async" data-image-key="${esc(g.key)}" data-attempt="${detail?imageIndex:0}">`:'<span class="photo-missing">Bild wird beim Import gesichert</span>'}
function render(reset=true){renderPresets();if(reset)visible=40;const list=selectedGroups();$('#viewtitle').textContent=view==='all'?'Alle Finds':view==='saved'?'Deine Merkliste':'Meine Marken & Modelle';$('#summary').textContent=view==='saved'?'Auf diesem Gerät gespeichert. Bilder und Angebote direkt hier vergleichen.':groups.length.toLocaleString('de-DE')+' Produkte · gleiche Produktlinks zusammengefasst · '+groups.filter(g=>g.cached).length.toLocaleString('de-DE')+' mit gespeichertem Vorschaubild';$('#headerinfo').textContent=catalog.sources.length+' Quellen';$('#savedcount').textContent=Object.keys(favorites).length;$('#count').textContent=list.length.toLocaleString('de-DE')+(list.length===1?' Produkt':' Produkte');$('#empty').hidden=!!list.length;$('#empty').textContent=view==='saved'?'Noch nichts gemerkt – tippe auf das Lesezeichen am Produkt.':'Keine passenden Produkte. Filter zurücksetzen oder eine andere Kategorie wählen.';$('#more').hidden=visible>=list.length;$('#more').textContent='Weitere '+Math.min(40,list.length-visible)+' anzeigen';$('#cards').innerHTML=list.slice(0,visible).map(g=>`<article class="card"><button class="bookmark" data-save="${esc(g.key)}" aria-label="${favorites[g.key]?'Nicht mehr merken':'Merken'}: ${esc(g.name)}" aria-pressed="${!!favorites[g.key]}">${favorites[g.key]?'♥':'♡'}</button><button class="photo-button" data-detail="${esc(g.key)}" aria-label="Details und Bild: ${esc(g.name)}">${imgHTML(g)}</button><div class="cardinfo"><span class="kicker">${esc(g.category.main)} · ${esc(g.category.sub)}</span><button class="cardname" data-detail="${esc(g.key)}"><h2>${esc(g.name)}</h2></button><p class="price">${g.price===null?'Preis offen':(g.offers.length>1?'ab ':'')+money(g.price)}</p><p class="offerhint">${new Set(g.offers.map(o=>o.shop)).size} ${new Set(g.offers.map(o=>o.shop)).size===1?'Webseite':'Webseiten'} · ${new Set(g.references.map(r=>r.source)).size} ${new Set(g.references.map(r=>r.source)).size===1?'Quelle':'Quellen'}</p></div></article>`).join('');document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',b.dataset.view===view)});const categoryOrder=['Schuhe','Bekleidung','Uhren','Taschen','Accessoires','Technik','Wohnen','Freizeit','Weitere Artikel'];const categories=['',...categoryOrder.filter(c=>groups.some(g=>g.category.main===c))];$('#categories').innerHTML=categories.map(c=>`<button data-category="${esc(c)}" class="${c===category?'active':''}" aria-pressed="${c===category}">${esc(c||'Alle Kategorien')}</button>`).join('');$('#filtercount').textContent=['brand','subcategory','shop','source','imagefilter'].filter(id=>$('#'+id).value).length||'';remember()}
function sellerOf(p){return M.sellerUrl(p.url)}
function legacySellerOf(p){let id=M.identity(p.url),m=id.match(/^(weidian|taobao|1688):(\d+)$/);if(!m)return '';try{let u=new URL(p.url);for(let qs of [u.searchParams,new URLSearchParams(u.hash.split('?')[1]||'')])for(let k of ['url','productUrl','productLink']){let v=qs.get(k);if(!v)continue;for(let i=0;i<3&&!/^https?:\/\//.test(v);i++)v=decodeURIComponent(v);if(M.safe(v))return v}}catch{}return ''}
function renderDetail(){const g=groupMap.get(detailKey)||favorites[detailKey];if(!g)return;imageIndex=Math.min(imageIndex,Math.max(0,g.images.length-1));$('#detailbody').innerHTML=`<div class="detailgrid"><div><div class="detailphoto">${imgHTML(g,true)}</div>${g.images.length>1?`<div class="gallerycontrols"><button id="image-prev" aria-label="Vorheriges Bild">←</button><span>Bild ${imageIndex+1} von ${g.images.length}</span><button id="image-next" aria-label="Nächstes Bild">→</button></div>`:''}</div><div class="detailtext"><p class="eyebrow">${esc(g.category.main)} / ${esc(g.category.sub)}</p><h2>${esc(g.name)}</h2><p class="price">${g.price===null?'Preis offen':money(g.price)}</p><button class="detail-save" data-save="${esc(g.key)}" aria-pressed="${!!favorites[g.key]}">${favorites[g.key]?'♥ Gemerkt – entfernen':'♡ In die Merkliste'}</button><p class="detail-note">Tabellenpreise ohne Versand. Händler nur öffnen, wenn du das Angebot genauer ansehen möchtest.</p><h3>Angebote & Quellen</h3>${g.offers.map(o=>`<div class="offer"><div class="offerhead"><span>${esc(o.shop)}</span><span>${Number.isFinite(o.euro)?money(o.euro):'Preis offen'}</span></div><small>${esc(o.name)}</small><small>${esc(o.raw||'')}${o.rateDate?' · Kurs '+esc(o.rateDate):''}</small><small>${esc(o.sourceInfo?.name||'Eigener Eintrag')}</small><div class="offeractions"><a href="${esc(M.safe(o.url))}" target="_blank" rel="noopener" referrerpolicy="no-referrer">Produkt beim Anbieter ↗</a>${o.sourceUrl?`<a href="${esc(M.safe(o.sourceUrl))}" target="_blank" rel="noopener">In der Quelle öffnen ↗</a>`:''}${sellerOf(o)?`<a href="${esc(M.safe(sellerOf(o)))}" target="_blank" rel="noopener">Original beim Verkäufer ↗</a>`:''}</div></div>`).join('')}<details class="detailrefs"><summary>Original-Quellen & Fundstellen (${g.references.length})</summary>${g.references.map(r=>r.sourceUrl?`<a href="${esc(M.safe(r.sourceUrl))}" target="_blank" rel="noopener">${esc(r.name)} · ${esc(r.location)} ↗</a>`:`<p>${esc(r.name)} · ${esc(r.location)}</p>`).join('')}</details></div></div>`;$('#image-prev')?.addEventListener('click',()=>{imageIndex=(imageIndex-1+g.images.length)%g.images.length;renderDetail()});$('#image-next')?.addEventListener('click',()=>{imageIndex=(imageIndex+1)%g.images.length;renderDetail()})}
function openDetail(key){if(!groupMap.has(key)&&!favorites[key])return;detailKey=key;imageIndex=0;remember();renderDetail();$('#detail').showModal();history.pushState({findsDetail:true},'','#produkt')}
function closeDetail(){if(history.state?.findsDetail)history.back();else{$('#detail').close();detailKey=''}}
document.addEventListener('click',event=>{const save=event.target.closest('[data-save]');if(save){toggleSaved(save.dataset.save);return}const detail=event.target.closest('[data-detail]');if(detail){openDetail(detail.dataset.detail);return}const tab=event.target.closest('[data-view]');if(tab){setView(tab.dataset.view);return}const preset=event.target.closest('[data-preset]');if(preset){restore(null);$('#brand').value=preset.dataset.preset;render();return}const chip=event.target.closest('[data-category]');if(chip){category=chip.dataset.category;populateSubcategories();render()}});
document.addEventListener('error',event=>{const img=event.target;if(!img.matches?.('img[data-image-key]'))return;const g=groupMap.get(img.dataset.imageKey)||favorites[img.dataset.imageKey];const next=Number(img.dataset.attempt)+1;if(g&&next<Math.min(g.images.length,4)){img.dataset.attempt=next;img.src=mediaUrl(g.images[next]);}else{let el=document.createElement('span');el.className='photo-missing';el.textContent='Bild konnte nicht geladen werden';img.replaceWith(el)}},true);
$('#close-detail').onclick=closeDetail;$('#detail').addEventListener('cancel',e=>{e.preventDefault();closeDetail()});window.addEventListener('popstate',()=>{if($('#detail').open)$('#detail').close();detailKey=''});window.addEventListener('pagehide',remember);document.addEventListener('visibilitychange',()=>{if(document.hidden)remember()});let scrollSave;window.addEventListener('scroll',()=>{clearTimeout(scrollSave);scrollSave=setTimeout(remember,250)},{passive:true});
$('#filter-toggle').onclick=()=>{let open=$('#filters').hidden;$('#filters').hidden=!open;$('#filter-toggle').setAttribute('aria-expanded',open);remember()};for(const id of ['query','brand','subcategory','shop','source','sort','imagefilter'])$('#'+id).addEventListener('input',()=>render());$('#reset-filters').onclick=()=>{restore(null);render()};$('#more').onclick=()=>{visible+=40;render(false)};$('#refresh-images').onclick=()=>location.reload();
$('#export-saved').onclick=()=>{const blob=new Blob([JSON.stringify({version:2,saved:favorites},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='daves-merkliste.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('#import-saved').onchange=async event=>{try{const f=event.target.files[0];if(!f)return;if(f.size>15_000_000)throw Error();const parsed=JSON.parse(await f.text());if(parsed.version!==2||!parsed.saved||typeof parsed.saved!=='object')throw Error();let n=0;for(const g of Object.values(parsed.saved)){if(!g||typeof g.key!=='string'||typeof g.name!=='string'||!Array.isArray(g.offers)||!g.offers.every(o=>M.safe(o.url)))throw Error();if(!favorites[g.key]){const rebuilt=M.build(g.offers,catalog.sources)[0];if(!rebuilt)throw Error();favorites[rebuilt.key]=groupMap.get(rebuilt.key)||rebuilt;n++}}saveFavorites();$('#savedstatus').textContent=n+' Einträge übernommen.';render(false)}catch{$('#savedstatus').textContent='Keine gültige Merkliste. Bitte eine exportierte Merkliste wählen.'}};
(function initialize(){catalog=window.findsCatalog;if(!catalog?.products)throw Error('Katalog fehlt');let local=read('daves-finds-v1',[]);if(Array.isArray(local))catalog.products.push(...local.filter(p=>M.safe(p.url)));groups=M.build(catalog.products,catalog.sources);groupMap=new Map(groups.map(g=>[g.key,g]));for(const k of Object.keys(favorites))if(groupMap.has(k))favorites[k]={...groupMap.get(k),savedAt:favorites[k].savedAt};$('#brand').innerHTML+=[...Object.keys(M.preferred)].map(b=>`<option>${esc(b)}</option>`).join('');$('#shop').innerHTML+=[...new Set(groups.flatMap(g=>g.offers.map(o=>o.shop)).filter(Boolean))].sort().map(s=>`<option>${esc(s)}</option>`).join('');$('#source').innerHTML+=catalog.sources.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');restore(navigation.views[view]);const duplicates=M.sourceDuplicates(catalog.products,catalog.sources);$('#duplicates').innerHTML=duplicates.length?'<h3>Doppelte und ähnliche Listen</h3>'+duplicates.map(d=>`<p><strong>${esc(d.name)} / ${esc(d.of)}</strong>: ${d.kind==='similar'?d.count+' gemeinsame Produktbezeichnungen. Links und Preise können abweichen.':d.count+' identische Produktlinks. In der Galerie zusammengefasst; beide Quellen bleiben erhalten.'}</p>`).join(''):'<p>Keine vollständigen Dubletten unter den importierten Quelllisten erkannt. Mehrfach gelistete Produkte sind zusammengefasst; alle Fundstellen bleiben erhalten.</p>';$('#sourcecards').innerHTML=catalog.sources.map(s=>`<div class="sourcecard">${s.url?`<a href="${esc(M.safe(s.url))}" target="_blank" rel="noopener">${esc(s.name)} ↗</a>`:esc(s.name)}<small>${esc(s.status||'Quelle erfasst')}</small></div>`).join('');$('#importsummary').textContent=catalog.products.length.toLocaleString('de-DE')+' Listeneinträge ergeben '+groups.length.toLocaleString('de-DE')+' unterschiedliche Produktlinks. Bilder mit temporären Google-Adressen werden beim Import auf GitHub gesichert.';$('#reports').innerHTML=(catalog.importReports||[]).map(r=>`<p><strong>${esc(r.source)}</strong>: ${r.status==='ok'?r.products+' Einträge · '+(r.cached_images??0)+' Bilder dauerhaft gespeichert':esc(r.reason)}</p>`).join('');const initialScroll=navigation.views[view]?.scroll||0;$('#views').hidden=false;render(false);requestAnimationFrame(()=>window.scrollTo(0,initialScroll));})();
